import os
import argparse
import random

import numpy as np
import pandas as pd


# ============================================================
# Select Active Learning samples and create cumulative pairs
#
# 1. Read the mean prediction scores and uncertainty generated by:
#      4_calculate_uncertainty.py
#
# 2. Exclude images already selected in previous iterations.
#
# 3. Select new images using:
#      - UBS: highest prediction variance
#      - RBS: random sampling
#
# 4. Add the newly selected images to the cumulative labeled set.
#
# 5. Create one random non-self pair for each image in the
#    cumulative labeled set.
#
# 6. Save:
#      - newly selected images
#      - cumulative labeled images
#      - cumulative RankNet pairs
#      - Active Learning summary and conditions
#
# AL_1 starts from the randomly sampled AL_0 dataset.
# AL_2 and later iterations load the cumulative dataset from
# the immediately preceding iteration.
#
# Input:
# Results/
#   <result_date>/
#     fold_<fold>/
#       <datatype>_mean_score_and_uncertainty.csv
#
# Add_dataset/
#   <al_id>/
#     AL_<previous_iteration>/
#       ...
#
# Output:
# Add_dataset/
#   <al_id>/
#     AL_<iteration>/
#       active_learning_summary_AL_<iteration>.csv
#       active_learning_condition_AL_<iteration>.csv
#       fold_<fold>/
#         <selection>/
#           <fold>_<datatype>_<selection>.csv
#           <fold>_<datatype>_<selection>_cumulative.csv
#           <fold>_<datatype>_pair_<selection>_cumulative.csv
#
# Previously selected images are excluded from subsequent
# Active Learning sampling.
# ============================================================


DEFAULT_SELECT_RATE = 0.05
DEFAULT_SELECTION = "UBS"
DEFAULT_SEED = 240119
INITIAL_SELECTION = "RBS"


def read_pred(root_dir, datatype):
    datafile = os.path.join(
        root_dir,
        f"{datatype}_mean_score_and_uncertainty.csv",
    )
    if not os.path.exists(datafile):
        raise FileNotFoundError(f"Prediction summary not found: {datafile}")

    data = pd.read_csv(datafile)
    required = {"filename", "label", "mean_score", "var_score"}
    missing = required - set(data.columns)
    if missing:
        raise ValueError(
            f"{datafile} is missing required columns: {sorted(missing)}"
        )

    data = data[["filename", "label", "var_score", "mean_score"]].copy()
    data["filename"] = data["filename"].astype(str)
    data["MayoLabel"] = data["label"].astype(float)
    data["var_score"] = data["var_score"].astype(float)
    data["mean_score"] = data["mean_score"].astype(float)

    return (
        data[["filename", "MayoLabel", "var_score", "mean_score"]]
        .drop_duplicates("filename")
        .reset_index(drop=True)
    )


def iteration_dir(root, al_id, iteration, fold, selection):
    return os.path.join(
        root,
        al_id,
        f"AL_{iteration}",
        f"fold_{fold}",
        selection,
    )


def cumulative_path(
    root,
    al_id,
    iteration,
    fold,
    datatype,
    selection,
):
    return os.path.join(
        iteration_dir(root, al_id, iteration, fold, selection),
        f"{fold}_{datatype}_{selection}_cumulative.csv",
    )


def load_previous_set(
    root,
    al_id,
    iteration,
    fold,
    datatype,
    selection,
):
    # AL_1 starts from the AL_0 random 20% image set.
    if iteration == 1:
        path = os.path.join(
            root,
            al_id,
            "AL_0",
            f"fold_{fold}",
            INITIAL_SELECTION,
            f"{fold}_{datatype}_{INITIAL_SELECTION}.csv",
        )
    else:
        path = cumulative_path(
            root,
            al_id,
            iteration - 1,
            fold,
            datatype,
            selection,
        )

    if not os.path.exists(path):
        raise FileNotFoundError(
            f"Previous labeled image set not found: {path}"
        )

    data = pd.read_csv(path)
    required = {"filename", "MayoLabel"}
    missing = required - set(data.columns)
    if missing:
        raise ValueError(
            f"{path} is missing required columns: {sorted(missing)}"
        )

    for col in ["var_score", "mean_score"]:
        if col not in data.columns:
            data[col] = np.nan

    data["filename"] = data["filename"].astype(str)
    data["MayoLabel"] = data["MayoLabel"].astype(float)

    return (
        data
        .drop_duplicates("filename")
        .reset_index(drop=True)
    )


def select_samples(data, n, selection, seed):
    if len(data) == 0:
        raise RuntimeError("No unlabeled samples remain.")

    n = min(n, len(data))

    if selection == "UBS":
        return (
            data
            .sort_values(
                ["var_score", "filename"],
                ascending=[False, True],
            )
            .head(n)
            .copy()
            .reset_index(drop=True)
        )

    if selection == "RBS":
        return (
            data
            .sample(
                n=n,
                replace=False,
                random_state=seed,
            )
            .reset_index(drop=True)
        )

    raise ValueError(f"Unknown selection method: {selection}")


def make_derangement(n, seed):
    if n < 2:
        raise RuntimeError(
            "At least two unique images are required to make pairs."
        )

    rng = random.Random(seed)
    idx = list(range(n))

    while True:
        shuffled = idx.copy()
        rng.shuffle(shuffled)
        if all(i != j for i, j in zip(idx, shuffled)):
            return np.asarray(shuffled, dtype=int)


def make_pairs(data, seed):
    data = (
        data
        .drop_duplicates("filename")
        .reset_index(drop=True)
    )

    pair_idx = make_derangement(len(data), seed)

    x1 = data.reset_index(drop=True)
    x2 = data.iloc[pair_idx].reset_index(drop=True)

    x1_label = x1["MayoLabel"].to_numpy(dtype=float)
    x2_label = x2["MayoLabel"].to_numpy(dtype=float)

    diff = x1_label - x2_label
    relative_label = np.empty(len(data), dtype=float)
    relative_label[diff > 0] = 1.0
    relative_label[diff == 0] = 0.5
    relative_label[diff < 0] = 0.0

    pair_df = pd.DataFrame({
        "x1_image": x1["filename"].to_numpy(),
        "x2_image": x2["filename"].to_numpy(),
        "x1_label": x1_label,
        "x2_label": x2_label,
        "relative_label": relative_label,
    })

    return pair_df


def process_one(
    result_date,
    al_id,
    iteration,
    fold,
    datatype,
    selection,
    select_rate,
    seed,
    results_root,
    output_root,
):
    result_path = os.path.join(
        results_root,
        result_date,
        f"fold_{fold}",
    )

    pred_data = read_pred(result_path, datatype)

    previous_data = load_previous_set(
        output_root,
        al_id,
        iteration,
        fold,
        datatype,
        selection,
    )

    already_selected = set(previous_data["filename"].astype(str))
    pool = pred_data[
        ~pred_data["filename"].isin(already_selected)
    ].copy()

    select_number = round(len(pred_data) * select_rate)
    select_number = max(1, min(select_number, len(pool)))

    selected = select_samples(
        pool,
        select_number,
        selection,
        seed + fold + iteration * 1000,
    )

    selected["selected_iteration"] = iteration
    selected["selected_result_date"] = result_date
    selected["selection"] = selection

    out_dir = iteration_dir(
        output_root,
        al_id,
        iteration,
        fold,
        selection,
    )
    os.makedirs(out_dir, exist_ok=True)

    selected_csv = os.path.join(
        out_dir,
        f"{fold}_{datatype}_{selection}.csv",
    )
    cumulative_csv = os.path.join(
        out_dir,
        f"{fold}_{datatype}_{selection}_cumulative.csv",
    )
    pair_csv = os.path.join(
        out_dir,
        f"{fold}_{datatype}_pair_{selection}_cumulative.csv",
    )

    for path in [selected_csv, cumulative_csv, pair_csv]:
        if os.path.exists(path):
            raise FileExistsError(
                f"Output already exists: {path}"
            )

    selected.to_csv(selected_csv, index=False)

    cumulative = pd.concat(
        [previous_data, selected],
        ignore_index=True,
        sort=False,
    )
    cumulative = (
        cumulative
        .drop_duplicates("filename")
        .reset_index(drop=True)
    )
    cumulative.to_csv(cumulative_csv, index=False)

    pair_df = make_pairs(
        cumulative,
        seed + fold + iteration * 1000,
    )
    pair_df.to_csv(pair_csv, index=False)

    print("")
    print(f"fold={fold} datatype={datatype} AL_{iteration}")
    print(f"  labeled before : {len(previous_data)}")
    print(f"  selected now   : {len(selected)}")
    print(f"  labeled after  : {len(cumulative)}")
    print(f"  pairs          : {len(pair_df)}")
    print(
        f"  self pairs     : "
        f"{int((pair_df['x1_image'] == pair_df['x2_image']).sum())}"
    )
    print(f"  pair csv       : {pair_csv}")

    return {
        "al_id": al_id,
        "result_date": result_date,
        "iteration": iteration,
        "fold": fold,
        "datatype": datatype,
        "selection": selection,
        "select_rate": select_rate,
        "labeled_before": len(previous_data),
        "selected_now": len(selected),
        "labeled_after": len(cumulative),
        "pair_number": len(pair_df),
        "selected_csv": selected_csv,
        "cumulative_csv": cumulative_csv,
        "pair_csv": pair_csv,
    }


def main():
    parser = argparse.ArgumentParser(
        description=(
            "Select Active Learning samples and create cumulative "
            "RankNet pairs in one step."
        )
    )

    parser.add_argument(
        "result_date",
        help="Result directory containing prediction uncertainty files.",
    )
    parser.add_argument(
        "--al-id",
        default="LIMUC_AL_001",
    )
    parser.add_argument(
        "--iteration",
        type=int,
        required=True,
    )
    parser.add_argument(
        "--folds",
        default="1,2,3,4,5",
    )
    parser.add_argument(
        "--datatype",
        default="train,valid",
    )
    parser.add_argument(
        "--selection",
        choices=["UBS", "RBS"],
        default=DEFAULT_SELECTION,
    )
    parser.add_argument(
        "--select-rate",
        type=float,
        default=DEFAULT_SELECT_RATE,
    )
    parser.add_argument(
        "--seed",
        type=int,
        default=DEFAULT_SEED,
    )
    parser.add_argument(
        "--results-root",
        default="./../Results",
    )
    parser.add_argument(
        "--output-root",
        default="./../Add_dataset",
    )

    args = parser.parse_args()

    if args.iteration < 1:
        raise ValueError("--iteration must be >= 1.")
    if not (0 < args.select_rate <= 1):
        raise ValueError("--select-rate must be > 0 and <= 1.")

    folds = [
        int(v.strip())
        for v in args.folds.split(",")
        if v.strip()
    ]
    datatypes = [
        v.strip()
        for v in args.datatype.split(",")
        if v.strip()
    ]

    allowed_datatypes = {"train", "valid"}

    if not set(datatypes).issubset(allowed_datatypes):
        raise ValueError(
            "--datatype must contain only 'train' and/or 'valid'. "
            "The test set must not be used for Active Learning selection."
        )

    summary = []

    for fold in folds:
        for datatype in datatypes:
            summary.append(
                process_one(
                    result_date=args.result_date,
                    al_id=args.al_id,
                    iteration=args.iteration,
                    fold=fold,
                    datatype=datatype,
                    selection=args.selection,
                    select_rate=args.select_rate,
                    seed=args.seed,
                    results_root=args.results_root,
                    output_root=args.output_root,
                )
            )

    summary_dir = os.path.join(
        args.output_root,
        args.al_id,
        f"AL_{args.iteration}",
    )
    os.makedirs(summary_dir, exist_ok=True)

    summary_path = os.path.join(
        summary_dir,
        f"active_learning_summary_AL_{args.iteration}.csv",
    )
    condition_path = os.path.join(
        summary_dir,
        f"active_learning_condition_AL_{args.iteration}.csv",
    )

    pd.DataFrame(summary).to_csv(
        summary_path,
        index=False,
    )

    pd.DataFrame([{
        "al_id": args.al_id,
        "iteration": args.iteration,
        "result_date": args.result_date,
        "selection": args.selection,
        "select_rate": args.select_rate,
        "folds": args.folds,
        "datatype": args.datatype,
        "seed": args.seed,
    }]).to_csv(
        condition_path,
        index=False,
    )

    print("")
    print("Finished.")
    print(f"Summary: {summary_path}")


if __name__ == "__main__":
    main()
